       | CB 8 ?b :: ?post => apply (z4sf_cb8_c8 m A pre post b) in H; cbn [app] in H
       | ?c :: ?l' => go constr:(pre ++ [c]) l'
       | [] => fail end in
    go constr:(@nil cell) cs end.

